for w,g,b in [('feter','Названо желание отпраздновать день рождения.','Просмотр квартиры и покупка книги не обозначают празднование.'),('fete','Собеседник приглашён на праздничную встречу.','Кино и просмотр квартиры не являются названным праздником.'),('anniversaire','Назван день рождения говорящего.','Запись и ужин не обозначают день рождения.'),('cadeau','Названа покупка подарка.','Торт — другая названная покупка; книга без контекста не названа подарком.'),('gateau','Назван торт для праздничной покупки.','Подарок и приглашение не являются словом торт.'),('feliciter','Реплика поздравляет собеседника с успехом.','Благодарность и вопрос о времени выполняют другие функции.'),('reussite','Назван успешный результат дела.','День рождения и подарок — другие понятия.'),('bon-anniversaire','Выбрано обычное поздравление с днём рождения.','Благодарность и пожелание спокойной ночи имеют другие поводы.'),('soiree','Благодарность относится к проведённому вечеру.','Подарок и само приглашение — другие причины благодарности.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

def reading(s,gs,vs,av,q,f,p,cs,a,g,b):return choose(s,'reading',gs,vs,av,q,fr(f,p),cs,a,g,b)
def vocabulary(s,gs,vs,av,q,cs,a,g,b):return choose(s,'vocabulary',gs,vs,av,q,ru('Выберите реплику по всем условиям.'),[fr(f,p) for f,p in cs],a,g,b)
def warmup(s,unit,lesson,task):
 prior=json.loads((OUT/f'{unit}.v1.json').read_text());t=copy.deepcopy(next(t for t in prior['sessions'][lesson-1]['tasks'] if t['id']==task));t['id']=f'Q{len(s["tasks"])+1:02}';s['tasks'].append(t)
 for o in t['objective_ids']:
  if o not in {x['id'] for x in s['objectives']}:s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))

